import { useState, type ReactNode } from 'react';
import { TriangleAlert } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { describeApiError } from '@/lib/api-error';

/** 文案契约：标题 / 消息 / 对象 / 后果 / 确认按钮文案，受控与触发器两种壳共用 */
interface ConfirmCopy {
  title: string;
  message: string;
  consequence?: string;
  objectName?: string;
  confirmText: string;
  destructive?: boolean;
}

interface ConfirmDialogBodyProps extends ConfirmCopy {
  pending: boolean;
  error: unknown;
  onCancel: () => void;
  onConfirm: () => void;
}

/** 确认弹窗内容（480 宽）：对象与后果分行呈现，后果用 warning 色；失败在弹窗内留痕可重试 */
function ConfirmDialogBody({
  title,
  message,
  consequence,
  objectName,
  confirmText,
  destructive,
  pending,
  error,
  onCancel,
  onConfirm,
}: ConfirmDialogBodyProps) {
  const copy = error ? describeApiError(error) : null;

  return (
    // 宽度：base-nova 的 AlertDialogContent 用 data-[size=default] 变体锁 max-w-xs/sm:max-w-sm，
    // 设计稿确认弹窗是 480（需容纳「对象 + 后果」两行），必须用同一变体覆盖，否则变体优先级压过裸工具类。
    <AlertDialogContent className="max-w-[480px] data-[size=default]:max-w-[480px] sm:max-w-[480px] data-[size=default]:sm:max-w-[480px]">
      <AlertDialogHeader>
        <AlertDialogTitle>{title}</AlertDialogTitle>
        {/* Base UI：asChild → render（Description 默认渲染 <p>，这里换成多段容器） */}
        <AlertDialogDescription render={<div className="space-y-2" />}>
          <p>{message}</p>
          {objectName ? <p className="font-medium text-foreground">{objectName}</p> : null}
          {consequence ? (
            <p className="flex items-start gap-2 text-warning">
              <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
              <span>{consequence}</span>
            </p>
          ) : null}
        </AlertDialogDescription>
      </AlertDialogHeader>
      {copy ? (
        <Alert variant="destructive">
          <AlertDescription>
            <p>{copy.message}</p>
            {copy.traceId ? <p className="mt-1 font-mono text-xs">traceId: {copy.traceId}</p> : null}
          </AlertDescription>
        </Alert>
      ) : null}
      <AlertDialogFooter>
        <AlertDialogCancel disabled={pending} onClick={onCancel}>
          取消
        </AlertDialogCancel>
        {/* preventDefault 阻止 Action 默认关闭：成功由 handleConfirm 关闭，失败留痕重试 */}
        <AlertDialogAction
          variant={destructive ? 'destructive' : 'default'}
          disabled={pending}
          onClick={(event) => {
            event.preventDefault();
            onConfirm();
          }}
        >
          {pending ? '正在处理…' : confirmText}
        </AlertDialogAction>
      </AlertDialogFooter>
    </AlertDialogContent>
  );
}

interface ConfirmDialogProps extends ConfirmCopy {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 确认动作：resolve 视为成功并关闭；reject 在对话框内展示错误，可重试或取消 */
  onConfirm: () => Promise<void>;
}

/** 危险操作确认（受控式，对齐 Vue EzConfirmButton：对象、后果、失败留痕） */
export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  message,
  consequence,
  objectName,
  confirmText,
  destructive,
  onConfirm,
}: ConfirmDialogProps) {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<unknown>(null);

  const handleOpenChange = (next: boolean) => {
    if (!next && pending) {
      return;
    }
    if (next) {
      setError(null);
    }
    onOpenChange(next);
  };

  const handleConfirm = async () => {
    setPending(true);
    setError(null);
    try {
      await onConfirm();
      onOpenChange(false);
    } catch (cause) {
      setError(cause);
    } finally {
      setPending(false);
    }
  };

  return (
    <AlertDialog open={open} onOpenChange={handleOpenChange}>
      <ConfirmDialogBody
        title={title}
        message={message}
        consequence={consequence}
        objectName={objectName}
        confirmText={confirmText}
        destructive={destructive}
        pending={pending}
        error={error}
        onCancel={() => handleOpenChange(false)}
        onConfirm={() => void handleConfirm()}
      />
    </AlertDialog>
  );
}

/**
 * 危险/需确认操作按钮（触发器式）：点击先弹出确认 AlertDialog，确认后才执行 onConfirm。
 * onConfirm 抛错时错误在弹窗内展示并保持打开，可重试或取消。
 */
export function ConfirmButton({
  triggerLabel,
  triggerVariant = 'outline',
  triggerSize = 'sm',
  triggerClassName,
  iconOnly = false,
  icon,
  title,
  message,
  consequence,
  objectName,
  confirmText = '确认',
  destructive,
  disabled,
  pending,
  onConfirm,
}: {
  triggerLabel: string;
  triggerVariant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
  triggerSize?: 'default' | 'sm' | 'lg' | 'icon';
  /** 触发器附加样式（danger 描边等设计形态），经 tailwind-merge 与变体基线合并 */
  triggerClassName?: string;
  iconOnly?: boolean;
  icon?: ReactNode;
  title: string;
  message: string;
  consequence?: string;
  objectName?: string;
  confirmText?: string;
  destructive?: boolean;
  disabled?: boolean;
  pending?: boolean;
  onConfirm: () => void | Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<unknown>(null);

  // 触发器是 destructive 时确认按钮同样用危险色，除非显式覆盖 destructive
  const destructiveTone = destructive ?? triggerVariant === 'destructive';

  const handleOpenChange = (next: boolean) => {
    if (!next && busy) {
      return;
    }
    if (next) {
      setError(null);
    }
    setOpen(next);
  };

  const handleConfirm = async () => {
    setBusy(true);
    setError(null);
    try {
      await onConfirm();
      setOpen(false);
    } catch (cause) {
      setError(cause);
    } finally {
      setBusy(false);
    }
  };

  return (
    <AlertDialog open={open} onOpenChange={handleOpenChange}>
      <AlertDialogTrigger
        render={
          <Button
            type="button"
            variant={triggerVariant}
            size={triggerSize}
            className={triggerClassName}
            disabled={disabled || pending}
            aria-label={iconOnly ? triggerLabel : undefined}
          />
        }
      >
        {icon}
        {iconOnly ? null : triggerLabel}
      </AlertDialogTrigger>
      <ConfirmDialogBody
        title={title}
        message={message}
        consequence={consequence}
        objectName={objectName}
        confirmText={confirmText}
        destructive={destructiveTone}
        pending={busy}
        error={error}
        onCancel={() => handleOpenChange(false)}
        onConfirm={() => void handleConfirm()}
      />
    </AlertDialog>
  );
}
